import{_ as a,c as n,o as r,ag as t}from"./chunks/framework.ARG558ZT.js";const m=JSON.parse('{"title":"Frontend learning path","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/index.md","filePath":"frontend/index.md"}'),i={name:"frontend/index.md"};function o(s,e,d,l,c,h){return r(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="frontend-learning-path" tabindex="-1">Frontend learning path <a class="header-anchor" href="#frontend-learning-path" aria-label="Permalink to “Frontend learning path”">​</a></h1><p>Build a usable document before adding a type system, component runtime or full-stack framework. The shared domain is a small public course catalogue; P-328 grows it into an authenticated management screen. <strong>All learner practice remains outstanding.</strong></p><h2 id="reading-order" tabindex="-1">Reading order <a class="header-anchor" href="#reading-order" aria-label="Permalink to “Reading order”">​</a></h2><ol><li><a href="./html-browser.html">HTML, browser behavior and accessibility</a>, then the ordered <a href="./../senior_growth/A11y/">accessibility lessons</a>.</li><li><a href="./../senior_growth/CSS/">CSS layout and cascade</a>, including intrinsic sizing and visible interaction states.</li><li><a href="./javascript.html">JavaScript ownership and asynchronous execution</a>, then <a href="./typescript.html">TypeScript contracts</a>.</li><li><a href="./react.html">React rendering and synchronization</a>, followed by forms, routing and component contracts.</li><li><a href="./next.html">Next.js and UI architecture</a>: use React and HTTP prerequisites before server/client caching or mutations.</li></ol><p><a href="./coverage-map.html">Coverage and ownership map</a> identifies canonical explanations and overlap decisions. <a href="./../workbench/frontend/">Workbench</a> contains reference implementations; <a href="./../practice/frontend/">practice sequence</a> defines learner deliverables separately.</p><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to “Boundaries”">​</a></h2><p>Browser DOM, input, focus, layout and navigation belong here. <a href="./../node-js/">Node.js</a> owns server runtime mechanics, streams and backend/database/deployment implementation. <a href="./../cs-foundations/">CS foundations</a> owns algorithm correctness and complexity. <a href="./../applied-ai/">Applied AI</a> owns retrieval and agent systems; its existing React streaming port is an optional consumer of these UI foundations.</p><p>Redux, advanced conditional types, custom composite widgets, virtualization, microfrontends and framework migrations are optional after the essential path. Choose a tool to meet an observed requirement rather than implement every comparison in the reference catalogue.</p>',8)])])}const f=a(i,[["render",o]]);export{m as __pageData,f as default};
